 "content": "def transform(grid):
    """Fill the interior of downward diagonal wedges from top-row markers."""
    out = [row[:] for row in grid]
    h = len(grid)
    if not h:
        return out
    w = len(grid[0])
    # Each top-row marker is the apex of a wedge whose sides descend one
    # column left/right per row. The outline remains unchanged; its interior
    # is filled with color 2, including portions clipped by the grid edges.
    for apex_col, color in enumerate(grid[0]):
        if color == 0:
            continue
        for depth in range(1, h):
            left = apex_col - depth
            right = apex_col + depth
            for col in range(max(0, left + 1), min(w - 1, right - 1) + 1):
                if grid[depth][col] == 0:
                    out[depth][col] = 2
    return out
